def experiment(inputs):
    import random
    import numpy as np
    random.seed(inputs.get('seed', 42))
    condition = inputs.get('condition', 'baseline')
    trials = inputs.get('trials', 10000)
    # Simulating variance in action-selection probability
    # Baseline: higher noise; Feedback: lower noise (stabilization)
    if condition == 'feedback_enabled':
        data = np.random.normal(0.5, 0.05, trials)
    else:
        data = np.random.normal(0.5, 0.15, trials)
    return {'normalized_variance': np.var(data), 'mean': np.mean(data)}

